#!/usr/bin/env python3
"""dock/ensemble_docking_pipeline — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "ensemble_docking_pipeline"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'ensemble_docking_pipeline', 'receptor': '', 'ligand': '', 'best_affinity': 0.0, 'poses': [{'rank': 1, 'affinity_kcal_per_mol': 0.0, 'pose_path': ''}], 'runtime_sec': 0.0, 'diagnostics': {'brain': 'dock', 'archetype': 'docking'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Ensemble docking:对 receptor 多个构象逐个 vina dock,取 best_of_n 作为最终 affinity。

    简化版:不真跑 MD cluster(需 mdtraj/MDAnalysis),接受 receptor_ensemble 字段(list of PDB);
    只给 receptor_pdb 单结构时降级为单构象 dock。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    receptors = payload.get("receptor_ensemble")
    if not receptors:
        rec = payload.get("receptor_pdb")
        receptors = [rec] if rec else []
    ligand_sdf = payload.get("ligand_library_sdf") or payload.get("ligand_sdf")
    n_modes = int(payload.get("num_modes", 9))
    exhaustiveness = int(payload.get("exhaustiveness", 8))

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_receptors": len(receptors), "scoring_method": payload.get("scoring_method", "best_of_n")}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": receptors[0] if receptors else "",
                "ligand": ligand_sdf or "", "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}

    if not receptors or not ligand_sdf:
        return {"ok": False, "error": "需要 receptor_ensemble (list) 或 receptor_pdb 之一,以及 ligand_library_sdf",
                "diagnostics": diagnostics}
    for r_pdb in receptors:
        if not _os.path.isfile(r_pdb):
            return {"ok": False, "error": f"receptor pdb 不存在: {r_pdb}", "diagnostics": diagnostics}
    if not _os.path.isfile(ligand_sdf):
        return {"ok": False, "error": f"ligand_sdf 不存在: {ligand_sdf}", "diagnostics": diagnostics}

    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="ensemble_dock_")
    diagnostics["out_dir"] = out_dir
    t0 = _time.time()
    all_poses = []
    for i, rec in enumerate(receptors):
        out_sdf = _os.path.join(out_dir, f"docked_rec{i}.sdf")
        vina_cmd = ["vina", "--receptor", rec, "--ligand", ligand_sdf,
                    "--autobox_ligand", ligand_sdf,
                    "--exhaustiveness", str(exhaustiveness), "--num_modes", str(n_modes),
                    "--out", out_sdf]
        r = run_tool(vina_cmd, timeout=int(payload.get("per_receptor_timeout_s", 600)))
        if not r["ok"]:
            continue
        # 解析 vina stdout 抽 affinity 表
        for ln in r["stdout"].splitlines():
            parts = ln.split()
            if len(parts) >= 4 and parts[0].isdigit():
                try:
                    all_poses.append({"rank": int(parts[0]), "receptor_idx": i,
                                      "affinity_kcal_per_mol": float(parts[1]), "pose_path": out_sdf})
                except ValueError:
                    continue

    all_poses.sort(key=lambda p: p["affinity_kcal_per_mol"])
    best_aff = all_poses[0]["affinity_kcal_per_mol"] if all_poses else 0.0
    return {"ok": True, "skill_id": SKILL, "receptor": receptors[0],
            "ligand": ligand_sdf, "best_affinity": best_aff,
            "poses": all_poses[:n_modes],
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
